            !card.capability_ids.is_empty()
                && !card.allowed_tools.is_empty()
                && card.output_contract == "TaskResultEnvelope"
                && card.lane == "hepta-backend"
                && card.manifest_report_only
                && !card.role_enforcement_enabled
        }));
    }

