    fn agent_role_agent_card_manifest_binds_requested_sources() {
        let report = hepta_work_graph_agent_role_agent_card_manifest_report_only_report();
        let source_ids = report
            .source_bindings
            .iter()
            .map(|binding| binding.source_surface_id)
            .collect::<Vec<_>>();

