fn work_graph_append_only_work_graph_events_event_store_cutover_readiness_readback_blockers_from(
    preview_report: &WorkGraphAppendOnlyWorkGraphEventsEventStoreCutoverReadinessPreviewReport,
) -> Vec<WorkGraphEventsEventStoreCutoverReadinessReadbackBlockerPreview> {
    let all_sources = preview_report
        .event_store_cutover_readiness_plans
        .iter()
        .map(|plan| plan.source_surface_id)
        .collect::<Vec<_>>();
    let partial_gap_sources = preview_report
        .blockers
        .iter()
        .find(|blocker| blocker.id == "canonical_adapter_projection_partial_or_gap")
        .map(|blocker| blocker.affected_source_surface_ids.clone())
        .unwrap_or_default();

    vec![
        readback_blocker(
            "append_only_work_graph_events_event_store_cutover_readiness_readback_not_executed",
            "high",
            all_sources.clone(),
            "keep event-store cutover_readiness readback as a preview until execution is explicitly enabled",
        ),
        readback_blocker(
            "append_only_work_graph_events_event_store_cutover_readiness_application_missing",
            "high",
            all_sources.clone(),
            "apply readback-verified event-store cutover_readiness contracts into no-persistence outcomes",
        ),
        readback_blocker(
            "append_only_work_graph_events_disabled",
            "high",
            all_sources.clone(),
            "keep WorkGraph event persistence disabled until event-store cutover_readiness application is verified",
        ),
        readback_blocker(
            "replay_readback_execution_disabled",
            "high",
            all_sources.clone(),
            "keep replay/readback execution disabled until append-only event persistence is promoted",
        ),
        readback_blocker(
            "runtime_canonical_adapter_enforcement_disabled",
            "high",
            all_sources,
            "keep runtime adapter enforcement disabled until append-only event persistence is promoted",
        ),
        readback_blocker(
            "canonical_adapter_projection_partial_or_gap",
            "high",
            partial_gap_sources,
            "close partial/gap adapter source mappings before authoritative event-store cutover_readiness",
        ),
    ]
}

