#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn event_store_cutover_readiness_readback_plans_preserve_no_execution() {
        let plans =
            work_graph_append_only_work_graph_events_event_store_cutover_readiness_readback_plans_from(
                &sample_cutover_readiness_plans(),
            );

        assert_eq!(plans.len(), 2);
        assert!(plans.iter().all(|plan| {
            plan.readback_status == "readback_plan_ready"
                && plan.expected_stage_count == 6
                && plan.expected_evidence_field_count == 10
                && !plan.readback_execution_enabled
                && !plan.replay_execution_enabled
                && !plan.event_store_cutover_readiness_enabled
                && !plan.persists_work_graph_events
        }));
    }

    #[test]
    fn event_store_cutover_readiness_readback_assertions_do_not_enable_persistence() {
        let stage_assertions =
            work_graph_append_only_work_graph_events_event_store_cutover_readiness_stage_assertions_from(
                &sample_stages(),
            );
        let evidence_assertions =
            work_graph_append_only_work_graph_events_event_store_cutover_readiness_evidence_field_assertions_from(
                &sample_cutover_readiness_plans(),
            );

        assert!(
            stage_assertions
                .iter()
                .all(|assertion| assertion.contract_ready_preview
                    && !assertion.event_store_enabled_after_readback
                    && !assertion.execution_enabled_after_readback
                    && !assertion.persistence_enabled_after_readback)
        );
        assert!(
            evidence_assertions
                .iter()
                .all(|assertion| assertion.evidence_contract_ready_preview
                    && !assertion.persists_evidence_after_readback)
        );
    }

    #[test]
    fn event_store_cutover_readiness_readback_drift_detectors_cover_core_contracts() {
        let detectors =
            work_graph_append_only_work_graph_events_event_store_cutover_readiness_drift_detectors(
            );

        assert_eq!(detectors.len(), 7);
        assert!(detectors.iter().all(|detector| detector.drift_budget == 0));
        assert!(
            detectors
                .iter()
                .any(|detector| detector.id == "event_store_cutover_readiness_contract_drift")
        );
    }

