#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn event_store_cutover_replay_readback_execution_closure_readback_plans_preserve_no_execution()
    {
        let plans =
            work_graph_append_only_work_graph_events_event_store_cutover_replay_readback_execution_closure_readback_plans_from(
                &sample_cutover_replay_readback_execution_closure_plans(),
            );

        assert_eq!(plans.len(), 2);
        assert!(plans.iter().all(|plan| {
            plan.readback_status == "readback_plan_ready"
                && plan.expected_stage_count == 6
                && plan.expected_evidence_field_count == 10
                && !plan.readback_execution_enabled
                && !plan.replay_execution_enabled
                && !plan.event_store_cutover_replay_readback_execution_closure_enabled
                && !plan.persists_work_graph_events
        }));
    }

    #[test]
    fn event_store_cutover_replay_readback_execution_closure_readback_assertions_do_not_enable_persistence()
     {
        let stage_assertions =
            work_graph_append_only_work_graph_events_event_store_cutover_replay_readback_execution_closure_stage_assertions_from(
                &sample_stages(),
            );
        let evidence_assertions =
            work_graph_append_only_work_graph_events_event_store_cutover_replay_readback_execution_closure_evidence_field_assertions_from(
                &sample_cutover_replay_readback_execution_closure_plans(),
            );

        assert!(
            stage_assertions
                .iter()
                .all(|assertion| assertion.contract_ready_preview
                    && !assertion.event_store_enabled_after_readback
                    && !assertion.execution_enabled_after_readback
                    && !assertion.persistence_enabled_after_readback)
        );
        assert!(
