#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn event_store_cutover_terminal_operator_review_packet_readback_plans_preserve_no_execution() {
        let plans =
            work_graph_append_only_work_graph_events_event_store_cutover_terminal_operator_review_packet_readback_plans_from(
                &sample_cutover_terminal_operator_review_packet_plans(),
            );

        assert_eq!(plans.len(), 2);
        assert!(plans.iter().all(|plan| {
            plan.readback_status == "readback_plan_ready"
                && plan.expected_stage_count == 6
                && plan.expected_evidence_field_count == 10
                && !plan.readback_execution_enabled
                && !plan.replay_execution_enabled
                && !plan.event_store_cutover_terminal_operator_review_packet_enabled
                && !plan.persists_work_graph_events
        }));
    }

