    fn event_store_promotion_readback_side_effects_remain_disabled() {
        assert_eq!(
            WorkGraphAppendOnlyWorkGraphEventsEventStorePromotionReadbackPreviewSideEffects::none(),
            WorkGraphAppendOnlyWorkGraphEventsEventStorePromotionReadbackPreviewSideEffects {
                filesystem_written: false,
                graph_state_persisted: false,
