fn work_graph_events_event_store_cutover_readiness_rerun_source_decisions_from(
    previous_decisions: &[WorkGraphEventsEventStorePromotionRerunSourceDecisionPreview],
    application_outcomes: &[WorkGraphEventsEventStoreCutoverReadinessApplicationSourceOutcomePreview],
    application_blockers: &[WorkGraphEventsEventStoreCutoverReadinessApplicationBlockerPreview],
) -> Vec<WorkGraphEventsEventStoreCutoverReadinessRerunSourceDecisionPreview> {
    previous_decisions
        .iter()
        .map(|previous| {
            let covered = application_outcomes.iter().any(|outcome| {
                outcome.source_surface_id == previous.source_surface_id
                    && outcome.event_store_cutover_readiness_contract_ready_preview
                    && !outcome.ready_for_event_store_cutover_readiness
            });
            let residual_source_blocker_ids =
                source_blocker_ids(application_blockers, previous.source_surface_id);
            let decision = work_graph_events_event_store_cutover_readiness_rerun_decision(
                covered,
                &residual_source_blocker_ids,
            );

            WorkGraphEventsEventStoreCutoverReadinessRerunSourceDecisionPreview {
                source_surface_id: previous.source_surface_id,
                source_category: previous.source_category,
                previous_enforcement_decision: previous
                    .work_graph_events_event_store_promotion_rerun_enforcement_decision,
                work_graph_events_event_store_cutover_readiness_rerun_enforcement_decision:
                    decision,
                covered_by_event_store_cutover_readiness_application_preview: covered,
                event_store_cutover_readiness_contract_ready: covered,
                event_store_cutover_readiness_application_applied: false,
                append_only_work_graph_events_enabled: false,
                event_store_enabled: false,
                replay_readback_execution_enabled: false,
                runtime_canonical_adapter_enforcement_enabled: false,
                residual_source_blocker_ids,
                next_required_gate: next_gate_for_decision(decision),
            }
        })
        .collect()
}

fn work_graph_events_event_store_cutover_readiness_rerun_cleared_blockers_from(
    previous_decisions: &[WorkGraphEventsEventStorePromotionRerunSourceDecisionPreview],
    decision_deltas: &[WorkGraphEventsEventStoreCutoverReadinessRerunSourceDecisionPreview],
) -> Vec<WorkGraphEventsEventStoreCutoverReadinessRerunClearedBlockerPreview> {
    let before = previous_decisions
        .iter()
        .filter(|decision| {
            decision.work_graph_events_event_store_promotion_rerun_enforcement_decision
                == "deny_append_only_work_graph_events_disabled"
        })
        .map(|decision| decision.source_surface_id)
        .collect::<Vec<_>>();
    let after_count = decision_deltas
        .iter()
        .filter(|decision| {
            decision.work_graph_events_event_store_cutover_readiness_rerun_enforcement_decision
                == "deny_work_graph_events_event_store_cutover_readiness_application_missing"
        })
        .count();

    vec![WorkGraphEventsEventStoreCutoverReadinessRerunClearedBlockerPreview {
        id: "work_graph_events_event_store_cutover_readiness_application_required_for_enforcement",
        cleared_source_surface_ids: before.clone(),
        source_count_before: before.len(),
        source_count_after: after_count,
        closure_gate_id:
            WORK_GRAPH_APPEND_ONLY_WORK_GRAPH_EVENTS_EVENT_STORE_CUTOVER_READINESS_APPLICATION_PREVIEW_GATE,
    }]
}

fn work_graph_events_event_store_cutover_readiness_rerun_residual_blockers_from(
    application_blockers: &[WorkGraphEventsEventStoreCutoverReadinessApplicationBlockerPreview],
) -> Vec<WorkGraphEventsEventStoreCutoverReadinessRerunResidualBlockerPreview> {
    application_blockers
        .iter()
        .filter(|blocker| !cleared_application_blocker(blocker.id))
        .map(
