    previous_decisions
        .iter()
        .map(|previous| {
            let covered = application_outcomes.iter().any(|outcome| {
                outcome.source_surface_id == previous.source_surface_id
                    && outcome.event_store_cutover_side_effect_lock_contract_ready_preview
                    && !outcome.ready_for_event_store_cutover_side_effect_lock
