                source_blocker_ids(application_blockers, previous.source_surface_id);
            let decision = work_graph_events_event_store_cutover_side_effect_lock_rerun_decision(
                covered,
                &residual_source_blocker_ids,
            );

            WorkGraphEventsEventStoreCutoverSideEffectLockRerunSourceDecisionPreview {
                source_surface_id: previous.source_surface_id,
                source_category: previous.source_category,
                previous_enforcement_decision: previous
                    .work_graph_events_event_store_cutover_operator_review_packet_rerun_enforcement_decision,
                work_graph_events_event_store_cutover_side_effect_lock_rerun_enforcement_decision:
                    decision,
                covered_by_event_store_cutover_side_effect_lock_application_preview: covered,
                event_store_cutover_side_effect_lock_contract_ready: covered,
                event_store_cutover_side_effect_lock_application_applied: false,
                append_only_work_graph_events_enabled: false,
                event_store_enabled: false,
                replay_readback_execution_enabled: false,
                runtime_canonical_adapter_enforcement_enabled: false,
                residual_source_blocker_ids,
                next_required_gate: next_gate_for_decision(decision),
