fn work_graph_events_event_store_cutover_side_effect_lock_rerun_stages_from(
    decision_deltas: &[WorkGraphEventsEventStoreCutoverSideEffectLockRerunSourceDecisionPreview],
    event_store_cutover_side_effect_lock_outcome_count: usize,
) -> Vec<WorkGraphEventsEventStoreCutoverSideEffectLockRerunStagePreview> {
    let partial_gap_count = decision_deltas
        .iter()
        .filter(|decision| {
            decision
                .residual_source_blocker_ids
                .contains(&"canonical_adapter_projection_partial_or_gap")
        })
        .count();

    vec![
        rerun_stage(
            "work_graph_events_event_store_cutover_side_effect_lock_contracts",
            event_store_cutover_side_effect_lock_outcome_count,
            0,
            decision_deltas
                .iter()
                .filter(|decision| {
                    decision.covered_by_event_store_cutover_side_effect_lock_application_preview
                })
                .count(),
            vec!["work_graph_events_event_store_cutover_side_effect_lock_readiness_rerun_missing"],
        ),
        rerun_stage(
            "append_only_work_graph_events_persistence",
            decision_deltas.len(),
            0,
            0,
            vec!["append_only_work_graph_events_disabled"],
        ),
        rerun_stage(
            "event_store_cutover_side_effect_lock_readiness",
            decision_deltas.len(),
            0,
            0,
            vec!["append_only_work_graph_events_disabled"],
        ),
        rerun_stage(
            "replay_readback_execution_readiness",
            decision_deltas.len(),
            0,
            0,
            vec!["replay_readback_execution_disabled"],
        ),
        rerun_stage(
            "canonical_adapter_partial_gap_closure",
            partial_gap_count,
            0,
            0,
            vec!["canonical_adapter_projection_partial_or_gap"],
        ),
        rerun_stage(
            "runtime_canonical_adapter_enforcement_dry_run",
            decision_deltas.len(),
