    #[test]
    fn persistence_guard_rerun_moves_application_missing_to_zero() {
        let decisions = work_graph_events_persistence_guard_rerun_source_decisions_from(
            &sample_previous_decisions(),
            &sample_application_outcomes(),
            &sample_application_blockers(),
        );

        assert_eq!(decisions.len(), 2);
        assert!(decisions.iter().all(|decision| {
            decision.covered_by_persistence_guard_application_preview
                && decision.persistence_guard_contract_ready
                && !decision.persistence_guard_application_applied
                && decision.work_graph_events_persistence_guard_rerun_enforcement_decision
                    == "deny_append_only_work_graph_events_disabled"
                && decision.next_required_gate
                    == WORK_GRAPH_UNIFIED_PROJECTION_ENFORCEMENT_READINESS_WORK_GRAPH_EVENTS_PERSISTENCE_GUARD_RERUN_RECOMMENDED_NEXT_GATE
        }));
    }

